import * as fs from 'fs';
import * as path from 'path';
import * as zlib from 'zlib';
import { Repository, Item, Fluid, OreDict, Recipe } from '../repository';
import { SearchQuery } from '../searchQuery';
import { PageModel, RecipeModel, LinkAlgorithm } from '../page';
import { SolvePage } from '../solver';
import './setup';

// Generated by PackWriterTest.fixture(), not by the C# exporter.
function loadExport(): Repository {
    const bytes = zlib.gunzipSync(fs.readFileSync(path.join(__dirname, 'fixtures/direct-export.bin')));
    const buffer = new ArrayBuffer(bytes.length);
    new Uint8Array(buffer).set(bytes);
    return Repository.load(buffer);
}

function recipeNamed(repository: Repository, name: string): Recipe {
    return Array.from(repository.recipes, pointer => repository.GetObject(pointer, Recipe))
        .find(recipe => recipe.recipeType.name === name)!;
}

describe('Direct Java export compatibility', () => {
    let repository: Repository;
    beforeEach(() => { repository = loadExport(); });

    it('loads header collections, service ordering, and empty remaps', () => {
        expect(repository.items.length).toBe(11);
        expect(repository.fluids.length).toBe(1);
        expect(repository.recipes.length).toBe(2);
        expect(Array.from(repository.service, pointer => repository.GetObject(pointer, Item).name))
            .toEqual(['Quest Book', 'Anvil']);
        expect(repository.GetSlice(repository.elements[7]).length).toBe(0);
    });

    it('preserves alternatives, reverse links, slots, catalysts, and chances', () => {
        const macerator = recipeNamed(repository, 'Macerator');
        const variants = macerator.items[0].goods as OreDict;
        expect(variants.items.map(item => item.name)).toEqual(['Test Ore', 'Alternative Ore']);
        expect(Array.from(variants.items[1].consumption)).toContain(macerator.objectOffset);
        expect(macerator.items[2].slot).toBe(1);
        expect(macerator.items[2].probability).toBe(0.25);
        const blast = recipeNamed(repository, 'Electric Blast Furnace');
        expect(blast.items.find(entry => entry.goods.id === 'i:test:circuit:1')?.amount).toBe(0);
        const dust = repository.GetById<Item>('i:test:dust:0')!;
        expect(Array.from(dust.production)).toEqual([macerator.objectOffset]);
        expect(Array.from(dust.consumption)).toEqual([blast.objectOffset]);
        expect(dust.nbt).toBe('{quality:1}');
        expect(dust.tooltip).toBe('<span class="fmt-a">Rich in iron &amp; nickel</span>');
    });

    it('uses item-list indices for fluid containers and object pointers elsewhere', () => {
        const fluid = repository.GetById<Fluid>('f:test:nitrogen')!;
        const container = repository.GetObject(repository.items[fluid.containers[0]], Item);
        expect(container.name).toBe('Nitrogen Cell');
        expect(container.container?.fluid).toBe(fluid);
        expect(container.container?.amount).toBe(1000);
        expect(container.container?.empty.name).toBe('Empty Cell');
        expect(fluid.isGas).toBe(true);
    });

    it('loads machine associations, tier gaps, heat, doubles and layout dimensions', () => {
        const macerator = recipeNamed(repository, 'Macerator');
        expect(macerator.recipeType.singleblocks[0].name).toBe('Basic Macerator');
        expect(macerator.recipeType.singleblocks[1]).toBeNull();
        const blast = recipeNamed(repository, 'Electric Blast Furnace');
        expect(blast.recipeType.defaultCrafter.name).toBe('Electric Blast Furnace');
        expect(blast.recipeType.multiblocks[0]).toBe(blast.recipeType.defaultCrafter);
        expect(blast.gtRecipe.specialValue).toBe(1800);
        expect(blast.gtRecipe.MetadataByKey('fraction')).toBe(1.25);
        expect(blast.gtRecipe.voltage).toBe(120);
        expect(blast.gtRecipe.voltageTier).toBe(1);
        expect(blast.gtRecipe.durationSeconds).toBe(10);
        expect(Array.from(blast.recipeType.dimensions)).toEqual([3, 1, 1, 1, 1, 1, 1, 1]);
    });

    it('supports ordinary and one-character searches with Java-generated masks', () => {
        const dust = repository.GetById<Item>('i:test:dust:0')!;
        expect(repository.IsObjectMatchingSearch(dust, new SearchQuery('dust'))).toBe(true);
        expect(repository.IsObjectMatchingSearch(dust, new SearchQuery('nickel'))).toBe(true);
        expect(repository.IsObjectMatchingSearch(dust, new SearchQuery('d'))).toBe(true);
        expect(repository.IsObjectMatchingSearch(dust, new SearchQuery('copper'))).toBe(false);
        expect(repository.IsObjectMatchingSearch(recipeNamed(repository, 'Macerator'), new SearchQuery('ore'))).toBe(true);
    });

    it('solves base singleblock production and applies EBF heat choices', () => {
        const log = jest.spyOn(console, 'log').mockImplementation(() => {});
        try {
            const macerator = recipeNamed(repository, 'Macerator');
            const blast = recipeNamed(repository, 'Electric Blast Furnace');
            const page = new PageModel({
                name: 'Direct export fixture', products: [], rootGroup: {
                    type: 'recipe_group', links: Object.fromEntries(Object.keys(repository.objectPositionMap).map(id => [id, LinkAlgorithm.Ignore])), elements: [
                        { type: 'recipe', recipeId: macerator.id, voltageTier: 0, fixedCrafterCount: 1 },
                        { type: 'recipe', recipeId: blast.id, voltageTier: 1, fixedCrafterCount: 1, choices: { coilTier: 0 } }
                    ]
                }
            });
            SolvePage(page);
            expect(page.status).toBe('solved');
            const first = page.rootGroup.elements[0] as RecipeModel;
            const second = page.rootGroup.elements[1] as RecipeModel;
            expect(first.recipesPerMinute).toBeCloseTo(12);
            expect(first.crafterCount).toBeCloseTo(1);
            expect(second.multiblockCrafter?.name).toBe('Electric Blast Furnace');
            expect(second.recipesPerMinute).toBeCloseTo(6);
            expect(second.powerFactor).toBeCloseTo(1);
            second.choices.coilTier = 1;
            SolvePage(page);
            expect(second.powerFactor).toBeCloseTo(0.95);
        } finally { log.mockRestore(); }
    });
});
